package com.wozos.shell;
import android.app.Activity;
import android.os.Bundle;
import android.content.Intent;
import android.content.pm.ResolveInfo;
import android.graphics.Color;
import android.graphics.Typeface;
import android.provider.Settings;
import android.view.*;
import android.widget.*;
import java.util.*;

public class Home extends Activity {
 private LinearLayout list; private String page="home"; private float x,y;
 private final int white=Color.WHITE, gray=0xff999999;
 @Override public void onCreate(Bundle b){super.onCreate(b); getWindow().setStatusBarColor(Color.BLACK);getWindow().setNavigationBarColor(Color.BLACK); getWindow().setFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN,WindowManager.LayoutParams.FLAG_FULLSCREEN);show("home");}
 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);show("home");}
 private int dp(float n){return (int)(n*Math.min(getResources().getDisplayMetrics().widthPixels/272f,getResources().getDisplayMetrics().heightPixels/480f)+.5f);}
 private TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(android.util.TypedValue.COMPLEX_UNIT_PX, size * Math.min(getResources().getDisplayMetrics().widthPixels / 272f, getResources().getDisplayMetrics().heightPixels / 480f));t.setTextColor(color);t.setTypeface(Typeface.create("sans-serif-light",Typeface.NORMAL));t.setIncludeFontPadding(false);return t;}
 private void row(String s,Runnable r){TextView t=text(s,30,white);t.setPadding(0,dp(4),0,dp(4));t.setMinHeight(dp(40));t.setFocusable(true);t.setOnClickListener(v->r.run());list.addView(t);}
 private void label(String s){TextView t=text(s,13,gray);t.setPadding(0,dp(16),0,dp(8));list.addView(t);}
 private ArrayList<String> entries(String key){String raw=getPreferences(0).getString(key,"");return new ArrayList<>(raw.isEmpty()?Collections.emptyList():Arrays.asList(raw.split(",")));}
 private void save(String key,ArrayList<String> a){getPreferences(0).edit().putString(key,android.text.TextUtils.join(",",a)).apply();}
 private void launch(String pkg){Intent i=getPackageManager().getLaunchIntentForPackage(pkg);if(i==null){notice();return;}try{startActivity(i);ArrayList<String> a=entries("history");a.remove(pkg);a.add(0,pkg);while(a.size()>12)a.remove(a.size()-1);save("history",a);}catch(Exception e){notice();}}
 private String appName(String pkg){try{return getPackageManager().getApplicationLabel(getPackageManager().getApplicationInfo(pkg,0)).toString().toLowerCase(Locale.ROOT);}catch(Exception e){return pkg;}}
 private void app(String name,String pkg){row(name,()->launch(pkg));list.getChildAt(list.getChildCount()-1).setOnLongClickListener(v->{ArrayList<String> a=entries("pins");if(a.contains(pkg)){a.remove(pkg);Toast.makeText(this,"unpinned",0).show();}else{a.add(pkg);Toast.makeText(this,"pinned to quickplay",0).show();}save("pins",a);if(page.equals("quickplay"))show(page);return true;});}
 private void notice(){Toast.makeText(this,"Application unavailable",Toast.LENGTH_SHORT).show();}
 private void settings(String action){try{startActivity(new Intent(action));}catch(Exception e){notice();}}
 private void controls(){label("device");row("wi-fi",()->settings(Settings.ACTION_WIFI_SETTINGS));row("bluetooth",()->settings(Settings.ACTION_BLUETOOTH_SETTINGS));row("battery",()->settings(Settings.ACTION_BATTERY_SAVER_SETTINGS));label("volume");android.media.AudioManager audio=(android.media.AudioManager)getSystemService(AUDIO_SERVICE);SeekBar volume=new SeekBar(this);volume.setMax(audio.getStreamMaxVolume(android.media.AudioManager.STREAM_MUSIC));volume.setProgress(audio.getStreamVolume(android.media.AudioManager.STREAM_MUSIC));volume.setProgressTintList(android.content.res.ColorStateList.valueOf(white));volume.setThumbTintList(android.content.res.ColorStateList.valueOf(white));volume.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int v,boolean user){if(user)audio.setStreamVolume(android.media.AudioManager.STREAM_MUSIC,v,0);}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});list.addView(volume);row("display",()->settings(Settings.ACTION_DISPLAY_SETTINGS));row("notifications",()->settings("android.settings.NOTIFICATION_SETTINGS"));}
 private void searchApps(){EditText input=new EditText(this);input.setSingleLine(true);input.setHint("search apps");input.setTextColor(white);input.setHintTextColor(gray);list.addView(input);LinearLayout results=new LinearLayout(this);results.setOrientation(1);list.addView(results);LinearLayout parent=list;Runnable refresh=()->{results.removeAllViews();list=results;String filter=input.getText().toString().toLowerCase(Locale.ROOT);List<ResolveInfo> apps=getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER),0);apps.sort(Comparator.comparing(r->r.loadLabel(getPackageManager()).toString(),String.CASE_INSENSITIVE_ORDER));String last="";Set<String> seen=new HashSet<>();for(ResolveInfo r:apps){String pkg=r.activityInfo.packageName;String name=r.loadLabel(getPackageManager()).toString().toLowerCase(Locale.ROOT);if(pkg.equals(getPackageName())||name.isEmpty()||!name.contains(filter)||!seen.add(pkg))continue;String letter=name.substring(0,1).toUpperCase(Locale.ROOT);if(!letter.equals(last)){label(letter);last=letter;}app(name,pkg);}list=parent;};input.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){refresh.run();}public void afterTextChanged(android.text.Editable e){}});refresh.run();parent.setFocusableInTouchMode(true);parent.requestFocus();}
 private void show(String p){page=p; LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(Color.BLACK);root.setPadding(dp(14),dp(8),dp(8),0);
 LinearLayout nav=new LinearLayout(this);for(String s:new String[]{"menu","quickplay"}){TextView t=text(s,15,s.equals(p)||s.equals("menu")&&p.equals("home")?white:gray);t.setPadding(0,dp(8),dp(26),dp(12));t.setOnClickListener(v->show(s.equals("menu")?"home":s));nav.addView(t);}root.addView(nav); TextClock clock=new TextClock(this);clock.setFormat12Hour("h:mm");clock.setFormat24Hour("HH:mm");clock.setTextColor(gray);clock.setTextSize(14);clock.setGravity(Gravity.RIGHT);LinearLayout status=new LinearLayout(this);status.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);status.addView(clock);android.os.BatteryManager bm=(android.os.BatteryManager)getSystemService(BATTERY_SERVICE);int level=bm.getIntProperty(android.os.BatteryManager.BATTERY_PROPERTY_CAPACITY);TextView battery=text(level>=0&&level<=100?"   "+level+"%":"",13,gray);status.addView(battery);status.setOnClickListener(v->show("controls"));root.addView(status);
 if(!p.equals("home")){TextView title=text(p,48,white);title.setSingleLine(true);root.addView(title);}
 ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setVerticalScrollBarEnabled(false);list=new LinearLayout(this);list.setOrientation(1);list.setPadding(0,dp(12),0,dp(24));scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);
 switch(p){case "home": for(String s:new String[]{"music","videos","pictures","radio","marketplace","internet","library","car","apps","settings"})row(s,()->show(s));break;
 case "quickplay":label("pins");for(String pkg:entries("pins"))app(appName(pkg),pkg);if(entries("pins").isEmpty())label("hold an app to pin it");label("history");for(String pkg:entries("history"))app(appName(pkg),pkg);break;
 case "car":label("apple carplay");row("connect",()->{Intent i=getPackageManager().getLaunchIntentForPackage("cn.manstep.phonemirrorBox");if(i!=null)launch("cn.manstep.phonemirrorBox");else Toast.makeText(this,"Install the compatible AutoKit receiver app first",Toast.LENGTH_LONG).show();});label("audio");row("bluetooth",()->settings(Settings.ACTION_BLUETOOTH_SETTINGS));row("display",()->settings(Settings.ACTION_DISPLAY_SETTINGS));row("device controls",()->show("controls"));break;
 case "controls":controls();break;case "radio":app("spotify radio","com.spotify.music");break;case "marketplace":app("aurora store","com.aurora.store");break;case "music":app("spotify","com.spotify.music");app("local music","org.lineageos.twelve");break;
 case "videos":app("max","com.wbd.stream");app("hulu","com.hulu.plus");app("files","com.android.documentsui");break;
 case "pictures":app("gallery","org.lineageos.glimpse");break;
 case "internet":app("brave","com.brave.browser");break;
 case "library":app("libby","com.overdrive.mobile.android.libby");app("files","com.android.documentsui");break;
 case "settings":row("notifications",()->settings("android.settings.NOTIFICATION_SETTINGS"));row("wireless",()->settings(Settings.ACTION_WIFI_SETTINGS));row("display",()->settings(Settings.ACTION_DISPLAY_SETTINGS));row("sound",()->settings(Settings.ACTION_SOUND_SETTINGS));row("system",()->settings(Settings.ACTION_SETTINGS));row("about",()->settings(Settings.ACTION_DEVICE_INFO_SETTINGS));row("home app",()->settings(Settings.ACTION_HOME_SETTINGS));break;
 case "apps":searchApps();break;}
 root.setAlpha(.65f);root.animate().alpha(1).setDuration(150).start();}
 @Override public boolean dispatchTouchEvent(android.view.MotionEvent e){if(e.getAction()==0){x=e.getX();y=e.getY();}if(e.getAction()==1&&Math.abs(e.getX()-x)>dp(100)&&Math.abs(e.getY()-y)<dp(65)){MotionEvent cancel=MotionEvent.obtain(e);cancel.setAction(MotionEvent.ACTION_CANCEL);super.dispatchTouchEvent(cancel);cancel.recycle();show(page.equals("home")&&e.getX()<x?"quickplay":"home");return true;}return super.dispatchTouchEvent(e);}
 @Override public void onBackPressed(){show("home");}
}
